// ../../lib/db/src/schema/countries.ts
var countriesTable = pgTable(
  "sf_countries",
  {
    countryCode: varchar("country_code", { length: 2 }).primaryKey(),
    countryName: varchar("country_name", { length: 120 }).notNull(),
    phonePrefix: varchar("phone_prefix", { length: 8 }).notNull(),
    minPhoneDigits: integer("min_phone_digits").notNull(),
    maxPhoneDigits: integer("max_phone_digits").notNull(),
    enabled: boolean("enabled").notNull().default(true),
    signupEnabled: boolean("signup_enabled").notNull().default(false),
    depositEnabled: boolean("deposit_enabled").notNull().default(false),
    interNetworkEnabled: boolean("inter_network_enabled").notNull().default(false),
    internationalEnabled: boolean("international_enabled").notNull().default(false),
    payoutEnabled: boolean("payout_enabled").notNull().default(false),
    ussdCode: varchar("ussd_code", { length: 32 }),
    version: integer("version").notNull().default(1),
    createdBy: varchar("created_by", { length: 255 }).notNull(),
    updatedBy: varchar("updated_by", { length: 255 }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow()
  },
  (table) => ({
    countryCodeFormat: check(
      "sf_countries_code_format_check",
      sql`${table.countryCode} ~ '^[a-z]{2}$'`
    ),
    phonePrefixFormat: check(
      "sf_countries_phone_prefix_format_check",
      sql`${table.phonePrefix} ~ '^\\+[1-9][0-9]{0,3}$'`
    ),
    phoneDigitsRange: check(
      "sf_countries_phone_digits_range_check",
      sql`${table.minPhoneDigits} BETWEEN 4 AND 15 AND ${table.maxPhoneDigits} BETWEEN ${table.minPhoneDigits} AND 15 AND ${table.maxPhoneDigits} + length(${table.phonePrefix}) - 1 <= 15`
    ),
    ussdCodeFormat: check(
      "sf_countries_ussd_code_format_check",
      sql`${table.ussdCode} IS NULL OR (${table.ussdCode} ~ '^[*][0-9]+([*][0-9]+)*#$' AND length(${table.ussdCode}) <= 32)`
    )
  })
);
var insertCountrySchema = external_exports.object({
  countryCode: external_exports.string().regex(/^[a-z]{2}$/),
  countryName: external_exports.string().trim().min(2).max(120),
  phonePrefix: external_exports.string().regex(/^\+[1-9][0-9]{0,3}$/),
  minPhoneDigits: external_exports.number().int().min(4).max(15),
  maxPhoneDigits: external_exports.number().int().min(4).max(15),
  enabled: external_exports.boolean().default(true),
  signupEnabled: external_exports.boolean().default(false),
  depositEnabled: external_exports.boolean().default(false),
  interNetworkEnabled: external_exports.boolean().default(false),
  internationalEnabled: external_exports.boolean().default(false),
  payoutEnabled: external_exports.boolean().default(false),
  createdBy: external_exports.string().min(1).max(255),
  updatedBy: external_exports.string().min(1).max(255)
}).refine((country) => country.minPhoneDigits <= country.maxPhoneDigits, {
  path: ["maxPhoneDigits"],
  message: "Maximum phone length must be at least the minimum phone length."
});

